'use strict';
if(typeof uiCatalogue44!=='undefined'){uiCatalogue44.schedule=[...new Set([...(uiCatalogue44.schedule||[]),'工作排程','每週排程','每日排程','新增排程','新增當日工作紀錄','複製上週','複製排程','查看紀錄','人員','排程工作','工作回報','收／領料紀錄','紀錄日期','回報人','工作進度','照片（選填，手機可選照片；電腦可 Ctrl+V 貼上）'])];uiCatalogue44.admin=[...new Set([...(uiCatalogue44.admin||[]),'排程與工作紀錄匯出','資料類型','日期範圍','匯出內容','開始日期','結束日期','資料（CSV）','照片','匯出'])]}
const exportToday59=()=>new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Taipei'});
function exportPanel59(){
 const panel=document.createElement('section');panel.className='admin-card records-export-panel';panel.innerHTML='<h2>排程與工作紀錄匯出</h2><p class="muted">選擇紀錄類型、日期及匯出內容。照片會依類型與日期整理；收料照片以照片上傳日期篩選，寄出照片依寄出日期篩選。</p><form class="records-export-form"><fieldset><legend>資料類型</legend><label><input type="checkbox" name="type" value="weekly"> 每週排程</label><label><input type="checkbox" name="type" value="daily" checked> 每日工作紀錄</label><label><input type="checkbox" name="type" value="receipt"> 收料紀錄</label><label><input type="checkbox" name="type" value="shipment"> 寄出紀錄</label></fieldset><div class="form-grid"><label class="field">開始日期<input type="date" name="from" required></label><label class="field">結束日期<input type="date" name="to" required></label></div><fieldset><legend>匯出內容</legend><label><input type="checkbox" name="data" checked> 資料（CSV）</label><label><input type="checkbox" name="photos"> 照片</label></fieldset><button type="submit" class="primary">匯出</button><p class="muted records-export-status" role="status"></p></form>';
 const form=panel.querySelector('form'),today=exportToday59();form.elements.from.value=today.slice(0,7)+'-01';form.elements.to.value=today;
 form.onsubmit=async event=>{event.preventDefault();const types=[...form.querySelectorAll('[name="type"]:checked')].map(x=>x.value),from=form.elements.from.value,to=form.elements.to.value,includeData=form.elements.data.checked,includePhotos=form.elements.photos.checked,button=form.querySelector('button[type="submit"]'),status=panel.querySelector('.records-export-status');
  if(!types.length||!includeData&&!includePhotos){status.textContent='請選擇至少一種資料類型及匯出內容';return}if(from>to||!from||!to||Date.parse(to)-Date.parse(from)>366*86400000){status.textContent='日期範圍不可超過一年，且結束日期須晚於開始日期';return}
  button.disabled=true;try{
   status.textContent='正在讀取紀錄…';const query=new URLSearchParams({from,to,types:types.join(','),photos:includePhotos?'1':'0'}),response=await apiFetch('/api/records-export?'+query),payload=await response.json();if(!response.ok)throw Error(payload.error||'無法讀取紀錄');
   const rows={weekly:[['開始日期','結束日期','工作項目','負責人','工作內容','色塊','建立人','建立時間'],...(payload.weekly||[]).map(e=>[e.day,e.end_day,e.title,exportAssignee59(e.assignee),e.note,e.color,e.author_name,e.created_at])],daily:[['紀錄類型','日期','工作項目／回報內容','負責人','建立人','建立時間','照片檔名'],...(payload.daily||[]).map(e=>[e.record_kind,e.day,e.body||e.title||'',e.assignee||'',e.author_name,e.created_at,e.photo_name||''])],receipt:[['收料日期','專案','零件','數量','收料人','登記時間'],...(payload.receipt||[]).map(e=>[e.day,e.project,e.item,e.quantity,e.actor,e.created_at])],shipment:[['寄出日期','案件','送鍍次數','廠商','回貨日期','焊接人員','環片配置','備註'],...(payload.shipment||[]).map(e=>[e.day,e.project,e.number,e.vendor,e.returned,e.welder,JSON.stringify(e.groups||[]),e.note])]},labels={weekly:'每週排程',daily:'每日工作紀錄',receipt:'收料紀錄',shipment:'寄出紀錄'},entries=[];
   if(includeData)for(const type of types)entries.push({name:'資料/'+labels[type]+'.csv',data:platingCsv(rows[type])});
   if(includePhotos){const manifest=[['類型','日期','案件','人員','原始檔名','檔案位置']],counts=new Map();let size=0;for(const [index,photo]of (payload.photos||[]).entries()){status.textContent='正在整理照片 '+(index+1)+' / '+payload.photos.length;const r=await apiFetch(photo.url);if(!r.ok)throw Error('照片讀取失敗：'+(photo.name||photo.day));const contentType=r.headers.get('content-type')||'';if(!/^image\/(jpeg|png|webp)/.test(contentType))throw Error('照片格式不正確');const bytes=new Uint8Array(await r.arrayBuffer());size+=bytes.length;if(size>250*1024*1024)throw Error('照片總量超過 250 MB，請縮短日期範圍');const ext=contentType.includes('png')?'png':contentType.includes('webp')?'webp':'jpg',folder='照片/'+safeFileName(photo.type)+'/'+photo.day,person=safeFileName(photo.actor||'未記錄人員'),key=folder+'/'+person,n=(counts.get(key)||0)+1;counts.set(key,n);const name=key+'_'+String(n).padStart(2,'0')+'.'+ext;entries.push({name,data:bytes});manifest.push([photo.type,photo.day,photo.project||'',photo.actor||'',photo.name||'',name]);}entries.push({name:'照片清單.csv',data:platingCsv(manifest)});}
   const filename='紀錄匯出_'+from+'_'+to;if(includeData&&!includePhotos&&types.length===1){exportDownload59(new Blob([entries[0].data],{type:'text/csv;charset=utf-8'}),filename+'_'+labels[types[0]]+'.csv')}else exportDownload59(makeZip(entries),filename+'.zip');status.textContent='匯出完成';
  }catch(e){status.textContent=e.message||'匯出失敗'}finally{button.disabled=false}
 };return panel;
}
function exportAssignee59(value){try{const parsed=JSON.parse(value);return Array.isArray(parsed)?parsed.join('、'):value}catch{return value||''}}
function exportDownload59(blob,filename){const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=filename;link.click();setTimeout(()=>URL.revokeObjectURL(url),30000)}
const exportAdminBefore59=renderAdmin;renderAdmin=function(){if(currentUser.role!=='supervisor')return exportAdminBefore59();exportAdminBefore59();if(!canDo('records.export'))return;const backup=document.querySelector('[data-section-key="backup"]');if(backup)backup.append(exportPanel59());};
const exportPagesBefore59=managementPages;managementPages=function(){const pages=exportPagesBefore59();if(canDo('records.export')&&currentUser.role!=='supervisor')pages.push({id:'records-export',title:'資料／照片匯出'});return pages};
const exportRenderBefore59=render;render=function(){exportRenderBefore59();if(location.hash==='#records-export'&&canDo('records.export')&&currentUser.role!=='supervisor')document.querySelector('main')?.append(exportPanel59())};
